mapper.select:
select c1.C_Name as saGcUnitName, c2.C_Name as saUnitName, c1.C_Abbreviation as saGcUnitAbbName, c2.C_Abbreviation as saUnitAbbName, c1.C_Name_History as saGcUnitNameHistory, c2.C_Name_History as saUnitNameHistory,
mn.* from Subcontract_Apply mn left join SYS_Company c1 on mn.Sa_Gc_Unit=c1.C_Id left join SYS_Company c2 on mn.Sa_Unit=c2.C_Id
where 1=1
and mn.Te_Id = #{params.teId}
and mn.Sa_Gc_Unit = #{params.saGcUnit}
and mn.Sa_Unit = #{params.saUnit}
and mn.P_Id=#{params.pId}
and likePname(#{params.pName},pro.P_Id)=true
and pro.P_Name like concat('%',#{params.pName},'%')
and mn.Sa_Title like concat('%',#{params.saTitle},'%')
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Sa_Create_Time desc
